import numpy as np

def r(x):
    # Move input x towards the upper asymptotic boundary (1.0) using a fixed step.
    # This structurally differs from scaling or constant mapping by saturating at the boundary.
    return min(1.0, x + 0.2)

def R(y_orig, y_new):
    # Gate validity: ensure outputs are finite for the statistical test.
    # We do not filter by the inequality y_new > y_orig here to allow the Wilcoxon test
    # to detect violations (diffs <= 0) in the underlying implementation.
    return np.isfinite(y_orig) and np.isfinite(y_new)
